def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def sections(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)
                if bounds[i] + 1 < bounds[i + 1]]

    row_sections = sections(h, sep_rows)
    col_sections = sections(w, sep_cols)

    separator_cells = set(sep_rows)
    values = [
        grid[r][c]
        for r in range(h) if r not in separator_cells
        for c in range(w) if c not in sep_cols
    ]
    background = max(set(values), key=values.count)

    out = []
    for r0, r1 in row_sections:
        row = []
        for c0, c1 in col_sections:
            anomalies = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if anomalies >= 2 else background)
        out.append(row)
    return out
